package com.brandempiricism.etocrm.prospecting.match;
import jakarta.persistence.*;import java.time.*;import java.util.UUID;
@Entity @Table(name="capability_match") class MatchEntity{@Id UUID id;UUID accountId;UUID signalId;UUID capabilityId;String accountName;String capabilityName;String owner;String hypothesis;String nextAction;LocalDate nextActionDate;@Enumerated(EnumType.STRING)MatchStatus status;Instant createdAt;String createdBy;protected MatchEntity(){}MatchEntity(UUID id,UUID accountId,UUID signalId,UUID capabilityId,String accountName,String capabilityName,String owner,String hypothesis,String nextAction,LocalDate nextActionDate,MatchStatus status,Instant now,String actor){this.id=id;this.accountId=accountId;this.signalId=signalId;this.capabilityId=capabilityId;this.accountName=accountName;this.capabilityName=capabilityName;this.owner=owner;this.hypothesis=hypothesis;this.nextAction=nextAction;this.nextActionDate=nextActionDate;this.status=status;this.createdAt=now;this.createdBy=actor;}}
enum MatchStatus{DRAFT,ACTIVE}
